from collections import deque

# BFS Traversal
def bfs(graph, start):
    visited = set([start])
    queue   = deque([start])
    order   = []
    while queue:
        node = queue.popleft()    # FIFO — dequeue from front
        order.append(node)
        for neighbour in graph[node]:
            if neighbour not in visited:
                visited.add(neighbour)
                queue.append(neighbour)
    return order

graph = {0:[1,2], 1:[0,3,4], 2:[0,4], 3:[1], 4:[1,2]}
print(bfs(graph, 0))   # [0, 1, 2, 3, 4]

# BFS Shortest Path — returns distance from source to all vertices
def bfs_shortest(graph, start):
    dist    = {start: 0}
    queue   = deque([start])
    while queue:
        node = queue.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                queue.append(nb)
    return dist

print(bfs_shortest(graph, 0))  # {0:0, 1:1, 2:1, 3:2, 4:2}

# BFS Path Reconstruction
def bfs_path(graph, start, end):
    parent = {start: None}
    queue  = deque([start])
    while queue:
        node = queue.popleft()
        if node == end:
            break
        for nb in graph[node]:
            if nb not in parent:
                parent[nb] = node
                queue.append(nb)
    if end not in parent: return []
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = parent[node]
    return path[::-1]

print(bfs_path(graph, 0, 3))   # [0, 1, 3]

# DFS Recursive
def dfs_recursive(graph, node, visited=None, order=None):
    if visited is None: visited = set()
    if order   is None: order   = []
    visited.add(node)
    order.append(node)
    for nb in graph[node]:
        if nb not in visited:
            dfs_recursive(graph, nb, visited, order)
    return order

graph = {0:[1,2], 1:[0,3,4], 2:[0,4], 3:[1], 4:[1,2]}
print(dfs_recursive(graph, 0))  # [0, 1, 3, 4, 2]

# DFS Iterative (explicit stack)
def dfs_iterative(graph, start):
    visited = set()
    stack   = [start]
    order   = []
    while stack:
        node = stack.pop()        # LIFO — pop from top
        if node not in visited:
            visited.add(node)
            order.append(node)
            for nb in reversed(graph[node]):
                if nb not in visited:
                    stack.append(nb)
    return order

# Cycle Detection in Directed Graph
def has_cycle_directed(graph):
    WHITE, GREY, BLACK = 0, 1, 2
    colour = {v: WHITE for v in graph}

    def dfs(v):
        colour[v] = GREY          # mark as in-progress
        for nb in graph.get(v, []):
            if colour[nb] == GREY:  # back edge = cycle!
                return True
            if colour[nb] == WHITE and dfs(nb):
                return True
        colour[v] = BLACK         # fully processed
        return False

    return any(dfs(v) for v in graph if colour[v] == WHITE)

print(has_cycle_directed({0:[1], 1:[2], 2:[0]}))  # True  (cycle)
print(has_cycle_directed({0:[1], 1:[2], 2:[3]}))  # False

# Topological Sort using DFS (for DAGs)
def topological_sort(graph):
    visited = set()
    order   = []

    def dfs(v):
        visited.add(v)
        for nb in graph.get(v, []):
            if nb not in visited:
                dfs(nb)
        order.append(v)           # add AFTER visiting all descendants

    for v in graph:
        if v not in visited:
            dfs(v)
    return order[::-1]            # reverse for topological order

dag = {0:[1,2], 1:[3], 2:[3], 3:[4], 4:[]}
print(topological_sort(dag))   # [0, 2, 1, 3, 4] or similar valid order

# Count Connected Components
def count_components(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited    = set()
    components = 0

    def dfs(v):
        visited.add(v)
        for nb in graph[v]:
            if nb not in visited:
                dfs(nb)

    for v in range(n):
        if v not in visited:
            dfs(v)
            components += 1
    return components

print(count_components(5, [(0,1),(1,2),(3,4)]))  # 2

import heapq
from collections import defaultdict

def dijkstra(graph, start):
    dist = defaultdict(lambda: float('inf'))
    dist[start] = 0
    heap = [(0, start)]     # (distance, vertex)

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue         # stale entry — skip
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return dict(dist)

# Weighted directed graph: (neighbour, weight)
