# {0:0, 1:3, 2:1, 3:4, 4:7}

# Bellman-Ford — handles negative weights
def bellman_ford(vertices, edges, start):
    dist = {v: float('inf') for v in range(vertices)}
    dist[start] = 0
    # Relax all edges V-1 times
    for _ in range(vertices - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    # Check for negative cycle
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            return None   # negative cycle detected
    return dist

edges = [(0,1,4),(0,2,5),(1,2,-3),(2,3,2)]
print(bellman_ford(4, edges, 0))  # {0:0,1:4,2:1,3:3}

# Floyd-Warshall — all-pairs shortest paths
def floyd_warshall(n, edges):
    INF = float('inf')
    dp  = [[INF]*n for _ in range(n)]
    for i in range(n): dp[i][i] = 0
    for u, v, w in edges: dp[u][v] = w

    for k in range(n):           # intermediate vertex
        for i in range(n):       # source
            for j in range(n):   # destination
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j])
    return dp

edges = [(0,1,3),(0,3,7),(1,0,8),(1,2,2),(2,3,1),(3,0,2)]
result = floyd_warshall(4, edges)
for row in result: print(row)
